def psi(a, b, bins=10):
    q = np.quantile(a, np.linspace(0, 1, bins + 1))
    pa = np.histogram(a, q)[0] / len(a)
    pb = np.histogram(b, q)[0] / len(b)
    return np.sum((pb - pa) * np.log(pb / pa))
